def process_frame(frame, parameters):
    h, w = frame.shape[:2]
    # Adapt the reference's NV12 plane interface to this BGR image port.
    planar = cv2.cvtColor(frame, cv2.COLOR_BGR2YUV_I420).reshape(-1)
    y = planar[:h*w].reshape(h, w).copy()
    u = planar[h*w:h*w+h*w//4].reshape(h//2, w//2)
    v = planar[h*w+h*w//4:].reshape(h//2, w//2)
    uv = np.stack((u, v), axis=-1).astype(np.uint8)
    incoming_y = y.copy()
    def measure(name):
        if name == 'chroma_offset':
            a, b = uv[::4, ::4].reshape(-1, 2).astype(np.float32).mean(axis=0) - 128.0
            return float(np.hypot(a, b) / 128.0)
        luma = (incoming_y[::4, ::4].astype(np.float32) - 16.0) / 219.0
        if name == 'p50': return float(np.median(luma))
        if name == 'dark_fraction': return float(np.mean(luma < 0.12))
        if name == 'clipped_fraction': return float(np.mean(luma >= 0.98))
        if name == 'rms_contrast': return float(luma.std())
        raise ValueError('unknown measure ' + repr(name))
    def strength(ramp):
        if not ramp: return 1.0
        best = 0.0
        for rule in ramp if isinstance(ramp, list) else [ramp]:
            gate = rule.get('only_if')
            if gate and measure(gate['measure']) < gate['min']: continue
            m = measure(rule['measure'])
            s = (rule['off'] - m) / (rule['off'] - rule['full'])
            best = max(best, min(max(s, 0.0), 1.0))
        return best
    ops = parameters.get('ops') or []
    for op in ops:
        if op['op'] != 'clahe_luma': raise ValueError('unknown op ' + repr(op['op']))
    strengths = [strength(op.get('ramp', parameters.get('ramp'))) for op in ops]
    if all(s <= 0.0 for s in strengths): return frame.copy()
    for op, s in zip(ops, strengths):
        if s <= 0.0: continue
        clahe = cv2.createCLAHE(clipLimit=float(op.get('clip_limit', 2.0)), tileGridSize=tuple(map(int, op.get('tiles', [8, 8]))))
        fixed = clahe.apply(np.ascontiguousarray(y))
        y[...] = fixed if s >= 1.0 else cv2.addWeighted(np.ascontiguousarray(y), 1.0-s, fixed, s, 0.0)
    return cv2.cvtColorTwoPlane(y, uv, cv2.COLOR_YUV2BGR_NV12)

return process_frame(p02i_frame, parameters)

# Initialize once for this input; retain association state across every frame.
tracks = {}  # track_id -> {'class_id', 'bbox_xyxy', 'last_frame'}
next_track_id = 1
def box_iou(a, b):
    x1 = max(a[0], b[0]); y1 = max(a[1], b[1])
    x2 = min(a[2], b[2]); y2 = min(a[3], b[3])
    intersection = max(0.0, x2-x1) * max(0.0, y2-y1)
    aa = max(0.0, a[2]-a[0]) * max(0.0, a[3]-a[1])
    bb = max(0.0, b[2]-b[0]) * max(0.0, b[3]-b[1])
    return intersection / (aa+bb-intersection) if aa+bb-intersection > 0 else 0.0

def process(detections, frame, source_meta, parameters):
    global next_track_id
    index = source_meta['frame_index']
    max_age = int(parameters['max_age_frames'])
    threshold = float(parameters['iou_threshold'])
    for track_id in list(tracks):
        if index - tracks[track_id]['last_frame'] > max_age: del tracks[track_id]
    pairs = []
    for di, detection in enumerate(detections):
        for track_id, track in tracks.items():
            if track['class_id'] != detection['class_id']: continue
            overlap = box_iou(track['bbox_xyxy'], detection['bbox_xyxy'])
            if overlap >= threshold: pairs.append((overlap, di, track_id))
    pairs.sort(key=lambda pair: (-pair[0], pair[1], pair[2]))
    assigned = {}
    used_tracks = set()
    for overlap, di, track_id in pairs:
        if di not in assigned and track_id not in used_tracks:
            assigned[di] = track_id
            used_tracks.add(track_id)
    for di, detection in enumerate(detections):
        if di not in assigned:
            assigned[di] = next_track_id
            next_track_id += 1
        track_id = assigned[di]
        tracks[track_id] = {'class_id': detection['class_id'], 'bbox_xyxy': list(detection['bbox_xyxy']), 'last_frame': index}
    annotated = frame.copy()
    objects = []
    for di, detection in enumerate(detections):
        track_id = assigned[di]
        obj = {'track_id': track_id, 'class_id': detection['class_id'], 'label': detection['label'], 'confidence': detection['confidence'], 'bbox_xyxy': list(detection['bbox_xyxy'])}
        objects.append(obj)
        x1, y1, x2, y2 = (int(round(v)) for v in obj['bbox_xyxy'])
        cv2.rectangle(annotated, (x1, y1), (x2, y2), (0, 255, 0), 2)
        cv2.putText(annotated, f"{obj['label']} #{track_id} {obj['confidence']:.2f}", (x1, max(15, y1-6)), cv2.FONT_HERSHEY_SIMPLEX, 0.5, (0, 255, 0), 1, cv2.LINE_AA)
    # Retained but unmatched IDs are not observations and are not emitted.
    record = {'input_id': source_meta['input_id'], 'frame_index': index, 'timestamp_s': source_meta['timestamp_s'], 'objects': objects}
    return annotated, record

return process(p06i_detections, p06i_frame, p06i_meta, parameters)
